package com.termux.app.workspace;
import android.app.*;import android.webkit.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;import java.io.*;import java.util.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class ChatFileViewerLimitsTest {
 File file;static final long M=1024L*1024;
 @Before public void setup()throws Exception{file=File.createTempFile("preview-boundary-",".data");}
 @After public void end(){file.delete();}
 void size(long n,boolean gif)throws Exception{try(RandomAccessFile f=new RandomAccessFile(file,"rw")){f.setLength(n);if(gif&&n>=10){f.seek(0);f.write(new byte[]{'G','I','F','8','9','a',1,0,1,0});}}}
 @Test public void exactHtmlAndGifBoundariesAndEmptyFiles()throws Exception{for(boolean html:new boolean[]{true,false}){long cap=(html?32:64)*M;for(long bytes:new long[]{cap-1,cap}){size(bytes,!html);ChatFileViewer.Document d=new ChatFileViewer.Document(file,html);WebResourceResponse r=d.response(d.url);assertEquals(200,r.getStatusCode());r.getData().close();}for(long bytes:new long[]{cap+1,0}){size(bytes,!html);try{new ChatFileViewer.Document(file,html);fail();}catch(IOException e){assertEquals("PREVIEW_LIMIT",e.getMessage());}}}}
 @Test public void gifPixelLimitStillSixteenMillion()throws Exception{size(64*M,true);for(int width:new int[]{4000,4001}){try(RandomAccessFile f=new RandomAccessFile(file,"rw")){f.seek(6);f.write(width&255);f.write(width>>8);f.write(4000&255);f.write(4000>>8);}if(width==4000)new ChatFileViewer.Document(file,false);else try{new ChatFileViewer.Document(file,false);fail();}catch(IOException e){assertEquals("INVALID_GIF",e.getMessage());}}}
 @Test public void closeBeforeLayoutAndRepeatedReopenKeepNetworkFileAndRendererGuards()throws Exception{size(32*M,false);Activity a=Robolectric.buildActivity(Activity.class).setup().get();try{for(int n=0;n<8;n++){ChatFileViewer.Document d=new ChatFileViewer.Document(file,true);WebView w=ChatFileViewer.create(a,d,e->{});assertTrue(w.getSettings().getBlockNetworkLoads());assertFalse(w.getSettings().getAllowFileAccess());assertEquals(403,d.response("https://example.invalid/asset").getStatusCode());assertEquals(403,d.response("file:///private/other").getStatusCode());ChatFileViewer.release(w);ChatFileViewer.release(w);assertTrue(Shadows.shadowOf(w).wasDestroyCalled());}}finally{a.finish();}}
 @Test public void largeEmbeddedModelAndGifPreparationStreamWithoutWholeFileAllocation()throws Exception{for(boolean html:new boolean[]{true,false}){size((html?32:64)*M,!html);if(html)try(RandomAccessFile f=new RandomAccessFile(file,"rw")){f.write("<html><canvas></canvas><script>const vertices=[0,0,0];</script><!-- synthetic embedded 3D payload -->".getBytes(java.nio.charset.StandardCharsets.UTF_8));}Runtime rt=Runtime.getRuntime();long before=rt.totalMemory()-rt.freeMemory(),start=System.nanoTime(),bytes=0;ChatFileViewer.Document doc=new ChatFileViewer.Document(file,html);try(InputStream in=doc.response(doc.url).getData()){byte[] buffer=new byte[32768];int count;while((count=in.read(buffer))!=-1)bytes+=count;}long delta=rt.totalMemory()-rt.freeMemory()-before;assertEquals((html?32:64)*M,bytes);System.out.println("PREVIEW_STREAM_FIXTURE html="+html+" bytes="+bytes+" elapsedMs="+((System.nanoTime()-start)/1000000)+" heapDelta="+delta+"; no real WebView JS/WebGL/GIF render in Robolectric");}}
}
